8	/**
9	 * Hard duplicate detection on create: rejects (409) an owner whose {@code identityKey} equals that
10	 * of an existing owner. The single identity key (SHA-256 over normalized telephone, lower-cased
11	 * email and the last name's Soundex — see {@link OwnerIdentity}) is the whole definition of a
12	 * duplicate; there is no separate household-duplicate block.
13	 *
14	 * <p>Owners flagged {@code deleted} are ignored, so a soft-deleted record never blocks a recreate.
15	 * Runs after the email-domain blocklist (see {@link NormalizeOwnerEmail}) and after the telephone
16	 * has been normalized, so the key is computed over the same normalized inputs as the stored owners
17	 * it is compared against. Because the telephone is part of the key, two owners sharing a last name
18	 * and postcode but carrying different telephones are not hard duplicates — they fall through to the
19	 * soft signal (see {@link FlagPossibleDuplicate}).
20	 */
21	public class RejectDuplicateIdentity {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws DuplicateOwnerException {
24	        String identityKey = OwnerIdentity.identityKey(owner);
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (existing.getId() == null || existing.getId().equals(owner.getId())) {
27	                continue;
28	            }
29	            if (Boolean.TRUE.equals(existing.getDeleted())) {
30	                // A soft-deleted owner is not a duplicate.
31	                continue;
32	            }
33	            if (identityKey.equals(OwnerIdentity.identityKey(existing))) {
34	                throw new DuplicateOwnerException("An owner with the same identity already exists");
35	            }
36	        }
37	    }
